import SwiftData

@Model
class Note {
    var title: String
    var content: String
    var createdAt: Date
    var tags: [Tag]  // relationship inferred

    @Transient var wordCount: Int {
        content.split(separator: " ").count
    }

    init(title: String, content: String) {
        self.title = title
        self.content = content
        self.createdAt = .now
        self.tags = []
    }
}

// SwiftUI integration
struct NotesView: View {
    @Query(sort: \.createdAt, order: .reverse) var notes: [Note]
    @Environment(\.modelContext) var context

    var body: some View {
        List(notes) { note in
            Text(note.title)
        }
    }
}

// SwiftData — type-safe predicates
let today = Calendar.current.startOfDay(for: .now)
let predicate = #Predicate<Note> { note in
    note.createdAt >= today && note.title.contains("meeting")
}

// In SwiftUI with @Query
@Query(
    filter: #Predicate<Note> { $0.tags.count > 0 },
    sort: [
        SortDescriptor(\.createdAt, order: .reverse)
    ]
)
var taggedNotes: [Note]

// Programmatic fetch
func searchNotes(keyword: String) throws -> [Note] {
    let descriptor = FetchDescriptor<Note>(
        predicate: #Predicate { $0.content.contains(keyword) },
        sortBy: [SortDescriptor(\.createdAt)]
    )
    return try context.fetch(descriptor)
}

@main
struct MyApp: App {
    var body: some Scene {
        WindowGroup {
            ContentView()
        }
        .modelContainer(for: [Note.self, Tag.self])
    }
}

// CRUD in a view
struct NoteEditor: View {
    @Environment(\.modelContext) var context

    func addNote() {
        let note = Note(title: "New", content: "")
        context.insert(note)
        // Auto-saved by SwiftUI
    }

    func deleteNote(_ note: Note) {
        context.delete(note)
    }
}

// Background context for heavy work
func importNotes(from data: [NoteDTO]) async throws {
    let container = try ModelContainer(for: Note.self)
    let bgContext = ModelContext(container)
    for dto in data {
        bgContext.insert(Note(title: dto.title, content: dto.body))
    }
    try bgContext.save()
}
